using System;
using System.IO;
using System.Text;
using System.Linq;
using System.Xml;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Globalization;

namespace Frociart {
 // A passive, conservative export. Analysis never executes a project or writes a file.
 internal static class FlowgorithmExport {
  internal sealed class Issue {
   internal readonly bool Error;internal readonly string FunctionId,NodeId,Code,Message,Suggestion;
   internal Issue(bool error,string scope,string node,string code,string message,string suggestion){Error=error;FunctionId=scope;NodeId=node;Code=code;Message=message;Suggestion=suggestion;}
  }
  internal sealed class TypeChoice {
   internal readonly string Key,FunctionId,NodeId,Name,Scope;
   internal TypeChoice(string scope,string node,string name,string label){FunctionId=scope;NodeId=node;Name=name;Scope=label;Key=TypeKey(scope,name);}
  }
  internal sealed class Result {
   internal readonly string Xml;internal readonly ReadOnlyCollection<ColorChoice> RequiredColors;internal readonly ReadOnlyCollection<Issue> Issues;internal readonly ReadOnlyCollection<TypeChoice> RequiredTypes;internal readonly ReadOnlyCollection<NameMapping> Names;
   internal bool CanExport {get{return Xml!=null&&!Issues.Any(i=>i.Error);}}
   internal Result(string xml,List<Issue> issues,List<TypeChoice> required,List<NameMapping> names,List<ColorChoice> colors){RequiredColors=colors.AsReadOnly();Xml=xml;Issues=issues.AsReadOnly();RequiredTypes=required.AsReadOnly();Names=names.AsReadOnly();}
  }
  internal sealed class ColorChoice {internal readonly string Key,FunctionId,NodeId,Original,Scope;internal ColorChoice(string function,string node,string color,string scope){FunctionId=function;NodeId=node;Original=color;Scope=scope;Key=(function??"")+":"+node;}}
  internal sealed class NameMapping {internal readonly string FunctionId,Original,Exported;internal NameMapping(string f,string o,string e){FunctionId=f;Original=o;Exported=e;}}
  internal static string TypeKey(string scope,string name){return(scope??"")+":"+name.ToLowerInvariant();}
  internal static Result Analyze(Diagram document,IDictionary<string,FlowDataType> choices=null){return Analyze(document,choices,null);}
  internal static Result Analyze(Diagram document,IDictionary<string,FlowDataType> choices,IDictionary<string,int> colors){return new Planner(document,choices,colors).Build();}
  private sealed class Stop:Exception {}
  private sealed class T {
   internal readonly int Kind;internal readonly bool Array;
   internal T(int kind,bool array=false){Kind=kind;Array=array;}
   internal bool Numeric {get{return !Array&&(Kind==1||Kind==2);}}
  }
  private static readonly T Unknown=new T(0),Integer=new T(1),Real=new T(2),Text=new T(3),Boolean=new T(4),Void=new T(5);
  private sealed class Symbol {
   internal string Original,Name,NodeId;internal T Type=Unknown;internal bool Fixed,Declared,Hoisted,Parameter,Reference,Input,ConstantPi;internal int WholeWrites;internal int? Length;
  }
  private sealed class Scope {
   internal FlowSource.Scope Source;internal FlowSourcePlan Plan;internal readonly HashSet<string> Callees=new HashSet<string>();internal bool NeedsInk;internal string Name,ReturnName,Ink;internal T ReturnType;
   internal readonly Dictionary<string,Symbol> Symbols=new Dictionary<string,Symbol>(StringComparer.OrdinalIgnoreCase);
   internal readonly HashSet<string> Used=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
   internal readonly List<X> Temporaries=new List<X>();internal readonly Dictionary<string,HashSet<string>> Dominators=new Dictionary<string,HashSet<string>>();
  }
  private sealed class V {
   internal readonly string Code;internal readonly T Type;internal readonly bool Stable;
   internal V(string code,T type,bool stable=false){Code=code;Type=type;Stable=stable;}
  }
  private sealed class X {
   internal readonly string Name;internal readonly string[] Attributes;internal readonly List<X> Children=new List<X>();
   internal X(string name,params string[] attributes){Name=name;Attributes=attributes;}
  }
  private sealed class Planner {
   readonly Diagram document;readonly IDictionary<string,FlowDataType> choices;readonly IDictionary<string,int> colors;readonly List<ColorChoice> requiredColors=new List<ColorChoice>();bool turtle,preserveInk;readonly List<Issue> issues=new List<Issue>();readonly List<TypeChoice> required=new List<TypeChoice>();
   readonly List<NameMapping> mappings=new List<NameMapping>();
   readonly List<Scope> scopes=new List<Scope>();readonly Dictionary<string,Scope> functions=new Dictionary<string,Scope>();readonly HashSet<string> global=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
   readonly Dictionary<string,FlowNode> nodes=new Dictionary<string,FlowNode>();Scope current;FlowSource.Block block;int sequence;bool boolHelper,quoteHelper,readBooleanHelper;
   static readonly string[] Reserved=("main and false mod not or pi true boolean integer real string abs cos random tan tostring arccos int sgn tochar toreal arcsin len sin tocode arctan log size tofixed char log10 sqrt tointeger ln eof arccosh cosh arcsinh sinh arctanh tanh").Split(' ');
   internal Planner(Diagram d,IDictionary<string,FlowDataType> c,IDictionary<string,int> colors){document=d;this.colors=colors==null?null:new Dictionary<string,int>(colors,StringComparer.Ordinal);choices=c==null?null:new Dictionary<string,FlowDataType>(c,StringComparer.Ordinal);foreach(string word in Reserved)global.Add(word);foreach(string helper in new[]{"fcReadBoolean","fcReadText","fcReadResult","fcReadStart","fcReadEnd","fcReadIndex","fcReadCode","fcReadToken","fcReadError","fcBooleanText","fcBooleanValue","fcBooleanResult","fcQuote","fcQuoteValue","fcQuoteResult","fcQuoteIndex","fcQuoteChar"})global.Add(helper);}
   internal Result Build(){
    try {
     var program=FlowSource.Compile(document);if(!program.CanGenerate){foreach(var i in program.Diagnostics.Where(i=>i.Error))issues.Add(new Issue(true,i.FunctionId,i.NodeId,i.Code,i.Message,i.Suggestion));return new Result(null,issues,required,mappings,requiredColors);}
     turtle=program.Scopes.SelectMany(s=>s.Blocks).Any(b=>FlowTurtle.IsTurtle(b.Kind));preserveInk=program.Scopes.SelectMany(s=>s.Blocks).Any(b=>b.Kind==NodeKind.TurtleClear);
     foreach(var graph in FunctionEditing.Graphs(document))foreach(var node in graph.Nodes)nodes.Add(node.Id,node);
     foreach(var s in program.Scopes){var scope=new Scope{Source=s,Plan=FlowSourcePlan.Create(s),Name=s.Id==null?"Main":Unique(Identifier(s.Name),global),ReturnType=new T((int)s.ReturnType,s.ReturnIsArray)};scopes.Add(scope);if(s.Id!=null)functions.Add(s.Id,scope);}
     foreach(var scope in scopes){if(scope.Source.Id!=null&&scope.Name!=scope.Source.Name)issues.Add(new Issue(false,scope.Source.Id,scope.Source.StartId,"renamed-function","La funzione «"+scope.Source.Name+"» diventa «"+scope.Name+"» nella copia Flowgorithm.","Il nome originale resta nel progetto Frociart."));Collect(scope);}
     foreach(var s in scopes)s.NeedsInk=preserveInk&&s.Source.Blocks.Any(b=>b.Kind==NodeKind.TurtlePen||b.Kind==NodeKind.TurtleClear);for(int pass=0;pass<scopes.Count;pass++)foreach(var s in scopes)if(s.Callees.Any(id=>functions[id].NeedsInk))s.NeedsInk=true;
     for(int pass=0;pass<512;pass++){bool changed=false;foreach(var scope in scopes){foreach(var n in scope.Source.Blocks){foreach(var w in n.Operation.Writes){var sym=scope.Symbols[w.Target.Name];if(!sym.Fixed){T inferred=Infer(w.Value,scope);if(w.Target.Index!=null)inferred=new T(inferred.Kind,true);changed|=Merge(sym,inferred);}}}if(scope.Source.ReturnType==FlowDataType.Auto){var t=scope.Symbols.ContainsKey(scope.Source.ReturnVariable)?scope.Symbols[scope.Source.ReturnVariable].Type:Unknown;if(t.Kind!=0&&!Same(scope.ReturnType,t)){scope.ReturnType=t;changed=true;}}}if(!changed)break;}
     var root=new X("flowgorithm","fileversion","4.2");var attributes=new X("attributes");attributes.Children.Add(new X("attribute","name","name","value",program.Title??"Diagramma"));root.Children.Add(attributes);
     foreach(var scope in scopes){current=scope;block=null;try{root.Children.Add(WriteScope(scope));}catch(Stop){}}
     if(issues.Any(i=>i.Error))return new Result(null,issues,required,mappings,requiredColors);
     if(readBooleanHelper)root.Children.Add(ReadBooleanHelper());if(boolHelper)root.Children.Add(BooleanHelper());if(quoteHelper)root.Children.Add(QuoteHelper());
     current=null;block=null;var xml=new StringBuilder("<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<!-- Creato con Frociart -->\n");Write(root,xml,0);
     if(Encoding.UTF8.GetByteCount(xml.ToString())>DiagramIO.MaxFileBytes)Fail("size","La conversione supera 4 MB.","Riduci il progetto prima di esportare.");
     // Round-trip acceptance is a boundary check, not execution of the exported program.
     try{FlowgorithmImport.DecodeText(xml.ToString());}catch(InvalidDataException ex){Fail("roundtrip","La conversione supera i limiti di struttura o delle espressioni: "+ex.Message,"Semplifica il blocco indicato; il progetto originale resta intatto.");}
     issues.Add(new Issue(false,null,null,"target-runtime","Tipi, limiti numerici, aspetto e messaggi di esecuzione seguono Flowgorithm.","Conserva il file .frociart per mantenere l'aspetto e tutte le impostazioni di Frociart."));
     return new Result(xml.ToString(),issues,required,mappings,requiredColors);
    }catch(Stop){return new Result(null,issues,required,mappings,requiredColors);}catch(XmlException){issues.Add(new Issue(true,current==null?null:current.Source.Id,block==null?null:block.Id,"xml-text","Un testo contiene caratteri non rappresentabili in XML.","Rimuovi i caratteri di controllo o Unicode incompleti dal titolo o dalla nota."));return new Result(null,issues,required,mappings,requiredColors);}
   }
   void Fail(string code,string message,string suggestion){issues.Add(new Issue(true,current==null?null:current.Source.Id,block==null?null:block.Id,code,message,suggestion));throw new Stop();}
   void Note(string code,string message){issues.Add(new Issue(false,current.Source.Id,block==null?null:block.Id,code,message,"Il progetto originale non viene modificato."));}
   static bool Same(T a,T b){return a.Kind==b.Kind&&a.Array==b.Array;}
   static T Union(T a,T b){if(b.Kind==0)return a;if(a.Kind==0)return b;if(a.Array!=b.Array)return new T(-1);if(a.Kind==b.Kind)return a;if((a.Kind==1||a.Kind==2)&&(b.Kind==1||b.Kind==2))return new T(2,a.Array);return new T(-1);}
   static bool Merge(Symbol s,T t){var combined=Union(s.Type,t);if(Same(combined,s.Type))return false;s.Type=combined;return true;}
   static string Identifier(string source){var s=new StringBuilder();foreach(char c in source??"")s.Append(c=='_'?'U':c);string name=s.ToString();if(name.Length==0||!Char.IsLetter(name[0]))name="valore"+name;return name;}
   static string Unique(string seed,HashSet<string> used){string name=seed.Substring(0,Math.Min(64,seed.Length));int i=2;while(!used.Add(name)){string suffix=(i++).ToString(CultureInfo.InvariantCulture);name=seed.Substring(0,Math.Min(64-suffix.Length,seed.Length))+suffix;}return name;}
   Symbol Add(Scope s,string name,string node){Symbol symbol;if(!s.Symbols.TryGetValue(name,out symbol)){symbol=new Symbol{Original=name,NodeId=node};s.Symbols.Add(name,symbol);}return symbol;}
   void Collect(Scope s){
    current=s;foreach(string name in global)s.Used.Add(name);foreach(var other in scopes)s.Used.Add(other.Name);
    Action<FlowSource.Expression,string> collect=(e,n)=>{if(e==null)return;var pending=new Stack<FlowSource.Expression>();pending.Push(e);while(pending.Count>0){var x=pending.Pop();if(x.FunctionId!=null)s.Callees.Add(x.FunctionId);if(x.Kind==FlowSource.ExpressionKind.Variable)Add(s,x.Text,n);foreach(var c in x.Children)pending.Push(c);}};
    foreach(var p in s.Source.Parameters){var v=Add(s,p.Name,s.Source.StartId);v.Parameter=true;v.Reference=p.ByReference;v.Fixed=true;v.Type=new T((int)p.Type,p.IsArray);if(p.Type==FlowDataType.Auto)Choice(s,v);}
    var written=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    foreach(var n in s.Source.Blocks){var o=n.Operation;if(o.Input!=null){var v=Add(s,o.Input.Name,n.Id);v.Input=true;written.Add(v.Original);collect(o.Input.Index,n.Id);}if(o.Declaration!=null){foreach(var name in o.Declaration.Names){var v=Add(s,name,n.Id);v.Fixed=v.Declared=true;v.Type=new T((int)o.Declaration.Type,o.Declaration.IsArray);if(o.Declaration.IsArray&&o.Declaration.Size.Kind==FlowSource.ExpressionKind.Number)v.Length=(int)o.Declaration.Size.Number;written.Add(name);}collect(o.Declaration.Size,n.Id);}foreach(var w in o.Writes){var writtenSymbol=Add(s,w.Target.Name,n.Id);if(w.Target.Index==null){writtenSymbol.WholeWrites++;if(!writtenSymbol.Declared&&w.Value.Kind==FlowSource.ExpressionKind.Vector)writtenSymbol.Length=w.Value.Children.Count;}written.Add(w.Target.Name);collect(w.Target.Index,n.Id);collect(w.Value,n.Id);}collect(o.Value,n.Id);}
    foreach(var v in s.Symbols.Values){v.Name=Unique(Identifier(v.Original),s.Used);if((v.Original.Equals("pi",StringComparison.OrdinalIgnoreCase)||v.Original=="π")&&!written.Contains(v.Original)&&!v.Parameter){v.ConstantPi=true;v.Type=Real;v.Name="pi";}if(!v.ConstantPi)mappings.Add(new NameMapping(s.Source.Id,v.Original,v.Name));if(!v.Parameter&&!v.Fixed&&(v.Original.Equals("pi",StringComparison.OrdinalIgnoreCase)||v.Original=="π"))v.Type=Real;if(v.Input&&!v.Fixed){v.Fixed=true;Choice(s,v);}if(!v.Name.Equals(v.Original,StringComparison.Ordinal))issues.Add(new Issue(false,s.Source.Id,v.NodeId,"renamed","«"+v.Original+"» diventa «"+v.Name+"» in Flowgorithm.","Il nome originale resta nel progetto Frociart."));}
    if(s.Source.Id!=null&&s.Source.ReturnType!=FlowDataType.Void)s.ReturnName=Unique("fcResult",s.Used);
    if(preserveInk)s.Ink=Unique("fcTurtleInk",s.Used);CollectColors(s);Dominators(s);
   }
   void Choice(Scope s,Symbol v){FlowDataType chosen;if(choices!=null&&choices.TryGetValue(TypeKey(s.Source.Id,v.Original),out chosen)&&(int)chosen>=1&&(int)chosen<=4){v.Type=new T((int)chosen,v.Type.Array);issues.Add(new Issue(false,s.Source.Id,v.NodeId,"chosen-type","«"+v.Original+"» usa il tipo "+TypeName(v.Type)+" solo nella copia Flowgorithm.","I valori accettati dall'input seguono il tipo scelto."));}else required.Add(new TypeChoice(s.Source.Id,v.NodeId,v.Original,s.Source.Name));}
   T Infer(FlowSource.Expression e,Scope s,int depth=0){if(e==null)return Void;if(depth>40)return Unknown;Func<FlowSource.Expression,T> child=c=>Infer(c,s,depth+1);switch(e.Kind){
    case FlowSource.ExpressionKind.Number:return e.Number==Math.Truncate(e.Number)&&Math.Abs(e.Number)<=9007199254740991d?Integer:Real;
    case FlowSource.ExpressionKind.Text:return Text;case FlowSource.ExpressionKind.Boolean:return Boolean;
    case FlowSource.ExpressionKind.Variable:return s.Symbols[e.Text].Type;
    case FlowSource.ExpressionKind.Index:var array=child(e.Children[0]);return array.Array?new T(array.Kind):Unknown;
    case FlowSource.ExpressionKind.Vector:T item=Unknown;foreach(var c in e.Children)item=Union(item,child(c));return new T(item.Kind,true);
    case FlowSource.ExpressionKind.Unary:return e.Text=="not"?Boolean:child(e.Children[0]);
    case FlowSource.ExpressionKind.Binary:if(new[]{"and","or","=","==","!=","<>","<","<=",">",">="}.Contains(e.Text))return Boolean;var a=child(e.Children[0]);var b=child(e.Children[1]);if(e.Text=="&"||e.Text=="+"&&(a.Kind==3||b.Kind==3))return Text;if(!a.Numeric||!b.Numeric)return Unknown;return e.Text=="/"||e.Text=="^"?Real:Union(a,b);
    case FlowSource.ExpressionKind.Call:if(e.FunctionId!=null)return functions[e.FunctionId].ReturnType;switch(e.Text){case "eof":return Boolean;case "len":case "size":case "int":case "floor":case "tointeger":case "tocode":case "sgn":case "random":return Integer;case "char":case "tochar":case "tostring":case "tofixed":return Text;case "abs":return child(e.Children[0]);case "array":case "vettore":return new T(e.Children.Count>1?child(e.Children[1]).Kind:1,true);default:return Real;}
    default:return Unknown;}}
   static string TypeName(T t){switch(t.Kind){case 1:return "Integer";case 2:return "Real";case 3:return "String";case 4:return "Boolean";default:return "None";}}
   X Declare(string name,T type,string size=""){return new X("declare","name",name,"type",TypeName(type),"array",type.Array?"True":"False","size",size);}
   V Temporary(T type){if(type.Array)Fail("array-value","Questa operazione richiede una copia temporanea del vettore.","Per questa struttura conserva il formato .frociart oppure esporta in Python o Java.");string name=Unique("fcTemp"+(++sequence).ToString(CultureInfo.InvariantCulture),current.Used);current.Temporaries.Add(Declare(name,type));return new V(name,type,true);}
   static X Assign(string name,string expression){return new X("assign","variable",name,"expression",expression);}
   V Capture(V value,List<X> output){if(value.Stable)return value;var temp=Temporary(value.Type);output.Add(Assign(temp.Code,value.Code));return temp;}
   string Truth(V v){if(v.Type.Array||v.Type.Kind!=4&&!v.Type.Numeric)Fail("condition-type","La condizione non ha un tipo logico o numerico determinabile.","Dichiara i tipi delle variabili e verifica la condizione.");return v.Type.Kind==4?v.Code:"("+v.Code+" <> 0)";}
   void RequireScalar(T t){if(t.Kind<1||t.Kind>4||t.Array)Fail("type","Il tipo di un valore non è convertibile in un tipo scalare Flowgorithm.","Dichiara un tipo coerente; per i vettori usa i singoli elementi.");}
   void Compatible(Symbol target,V v,bool indexed){T wanted=indexed?new T(target.Type.Kind):target.Type;RequireScalar(wanted);RequireScalar(v.Type);if(wanted.Numeric&&v.Type.Numeric){if((target.Parameter||target.Fixed&&!target.Declared)&&wanted.Kind==1&&v.Type.Kind!=1)Fail("integer-parameter","Il valore intero «"+target.Original+"» può ricevere un valore con decimali.","Usa una conversione esplicita dove desiderata: l'esportazione non tronca silenziosamente un parametro.");return;}if(wanted.Kind!=v.Type.Kind)Fail("assignment-type","«"+target.Original+"» cambia tipo o riceve un valore incompatibile.","Usa un tipo coerente prima di esportare.");}
   X WriteScope(Scope s){
    block=s.Source.Find(s.Source.StartId);if(!s.Plan.Structured)Fail("graph","Questo diagramma ha collegamenti che Flowgorithm non rappresenta direttamente.","Usa decisioni e cicli con un ingresso e un'uscita comuni, oppure conserva .frociart.");
    if(s.Source.Blocks.Any(n=>!n.Reachable)){block=s.Source.Blocks.First(n=>!n.Reachable);Fail("unreachable","Un blocco scollegato verrebbe perso nella conversione.","Collegalo al percorso o rimuovilo esplicitamente prima di esportare.");}
    foreach(var v in s.Symbols.Values){if(v.Declared&&!v.Parameter&&(v.Original.Equals("pi",StringComparison.OrdinalIgnoreCase)||v.Original=="π")&&v.Type.Kind!=2){block=s.Source.Find(v.NodeId);Fail("pi-shadow","La dichiarazione di pi può cambiare il valore della costante prima della dichiarazione.","Usa un nome diverso dalla costante pi per questo tipo.");}if(v.Type.Kind<1||v.Type.Kind>4){block=s.Source.Find(v.NodeId);Fail("unresolved-type","Scegli un tipo coerente per «"+v.Original+"».","Dichiara il tipo o scegli il tipo della copia Flowgorithm.");}}
    foreach(var p in s.Source.Parameters)if(p.IsArray&&!p.ByReference)Fail("array-by-value","«"+p.Name+"» usa una copia del vettore, mentre Flowgorithm passa i vettori per riferimento.","Questa esportazione non cambia il comportamento della funzione: conserva .frociart, Python o Java per questa firma.");
    if(s.Source.ReturnIsArray)Fail("array-return","Il risultato vettoriale non è rappresentabile da questa esportazione Flowgorithm.","Conserva .frociart, Python o Java per questa funzione.");
    var f=new X("function","name",s.Name,"type",s.Source.Id==null||s.Source.ReturnType==FlowDataType.Void?"None":TypeName(s.ReturnType),"variable",s.ReturnName??"");var parameters=new X("parameters");foreach(var p in s.Source.Parameters){var symbol=s.Symbols[p.Name];parameters.Children.Add(new X("parameter","name",symbol.Name,"type",TypeName(symbol.Type),"array",p.IsArray?"True":"False"));}if(s.NeedsInk&&s.Source.Id!=null){if(s.Source.Parameters.Count>=FunctionModel.MaxParameters)Fail("turtle-parameters","Questa funzione usa già il massimo di parametri e non può conservare il colore attraverso Pulisci nella copia Flowgorithm.","Riduci i parametri o conserva il progetto .frociart.");parameters.Children.Add(new X("parameter","name",s.Ink,"type","Integer","array","True"));}f.Children.Add(parameters);var body=new X("body");f.Children.Add(body);foreach(var note in s.Source.Notes)body.Children.Add(new X("comment","text",note.Text));if(preserveInk&&s.Source.Id==null){body.Children.Add(Declare(s.Ink,new T(1,true),"1"));body.Children.Add(Assign(s.Ink+"[0]","0"));}if(turtle&&s.Source.Id==null)Note("turtle-palette","La copia usa la palette Tartaruga di Flowgorithm. I colori adattati sono indicati nei controlli; il disegno originale resta intatto.");
    foreach(var v in s.Symbols.Values)if(!v.Parameter&&!v.ConstantPi&&(v.Declared||v.Type.Array&&v.WholeWrites==1)&&(!v.Type.Array||v.Length.HasValue&&v.Length.Value>0)){v.Hoisted=true;body.Children.Add(Declare(v.Name,v.Type,v.Type.Array?v.Length.Value.ToString(CultureInfo.InvariantCulture):""));if(v.Original.Equals("pi",StringComparison.OrdinalIgnoreCase)||v.Original=="π")body.Children.Add(Assign(v.Name,"pi"));}
    var code=Statements(s.Plan.Statements,false);foreach(var v in s.Symbols.Values)if(!v.Declared&&!v.Parameter&&!v.ConstantPi){if(v.Type.Array)continue;body.Children.Add(Declare(v.Name,v.Type));if(v.Original.Equals("pi",StringComparison.OrdinalIgnoreCase)||v.Original=="π")body.Children.Add(Assign(v.Name,"pi"));}
    if(s.ReturnName!=null)body.Children.Add(Declare(s.ReturnName,s.ReturnType));body.Children.AddRange(s.Temporaries);body.Children.AddRange(code);return f;
   }
   List<X> Statements(IEnumerable<FlowSourcePlan.Statement> statements,bool inLoop,bool nested=false){var result=new List<X>();foreach(var statement in statements){block=statement.Block;if(nested&&block.Operation.Declaration!=null&&block.Operation.Declaration.IsArray&&block.Operation.Declaration.Size.Kind!=FlowSource.ExpressionKind.Number)Fail("dynamic-array-scope","Un vettore di dimensione calcolata viene dichiarato dentro una decisione o un ciclo.","Dichiara il vettore prima della decisione o del ciclo, oppure usa una dimensione costante.");Metadata(result);if(statement.Kind==FlowSourcePlan.Kind.Instruction){Instruction(result,inLoop);continue;}var test=new List<X>();V condition=Expr(block.Operation.Value,test,null);string truth=Truth(condition);if(!statement.LoopOnTrue)truth="not ("+truth+")";result.AddRange(test);if(statement.Kind==FlowSourcePlan.Kind.If){var x=new X("if","expression",truth);var yes=new X("then");yes.Children.AddRange(Statements(statement.Body,inLoop,true));var no=new X("else");no.Children.AddRange(Statements(statement.Otherwise,inLoop,true));x.Children.Add(yes);x.Children.Add(no);result.Add(x);}else{var x=new X("while","expression",truth);x.Children.AddRange(Statements(statement.Body,true,true));block=statement.Block;var nextTest=new List<X>();Metadata(nextTest);nextTest.AddRange(test);x.Children.AddRange(nextTest);result.Add(x);}}return result;}
   void Metadata(List<X> output){var source=nodes[block.Id];if(!String.IsNullOrEmpty(source.Comment))output.Add(new X("comment","text",source.Comment));if(source.Kind!=NodeKind.Pause&&!source.Breakpoint)return;if(!source.Breakpoint){Note("disabled-pause","Un punto Pausa disattivato viene conservato come nota.");output.Add(new X("comment","text","Pausa disattivata"+(String.IsNullOrWhiteSpace(source.BreakpointCondition)?"":": "+source.BreakpointCondition)));return;}if(String.IsNullOrWhiteSpace(source.BreakpointCondition)){output.Add(new X("breakpoint","expression","","always","True"));return;}
